import { statSync } from "node:fs";

const LIMIT = 64 * 1024 * 1024; // Workers: 64 MiB uncompressed
const size = statSync("dist/index.js").size;
const mib = (n) => (n / 1024 / 1024).toFixed(2);
if (size > LIMIT) {
  console.error(`Bundle is ${mib(size)} MiB, over the ${mib(LIMIT)} MiB limit.`);
  process.exit(1);
}
console.log(`Bundle: ${mib(size)} MiB, headroom ${mib(LIMIT - size)} MiB.`);

import { readFileSync } from "node:fs";
import { gzipSync } from "node:zlib";

const MiB = 1048576;
const MAX_UNCOMPRESSED = 64 * MiB;
const bundle = readFileSync("dist/index.js");
console.log(`gzip (for reference): ${(gzipSync(bundle).length / MiB).toFixed(2)} MiB`);
if (bundle.length > MAX_UNCOMPRESSED) process.exit(1);
console.log(`size ${(bundle.length / MiB).toFixed(2)} MiB, ${((MAX_UNCOMPRESSED - bundle.length) / MiB).toFixed(2)} MiB left`);

import { statSync } from "node:fs";

const KIB = 1024;
const UNCOMPRESSED_CAP = 64 * KIB * KIB;
const size = statSync("dist/index.js").size;
if (size > UNCOMPRESSED_CAP) process.exit(1);
console.log(`${size} bytes, ${UNCOMPRESSED_CAP - size} bytes left`);

